pub fn adv(c: char) -> i16 {
    let cp = c as u32;
    if cp < 0x80 {
        return if cp >= 0x20 { 6 } else { 0 };
    }
    let mut lo = 0usize;
    let mut hi = RANGES.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (start, end, w) = RANGES[mid];
        if cp < start {
            hi = mid;
        } else if cp > end {
            lo = mid + 1;
        } else {
            return w as i16;
        }
    }
    8
}

/// Advance at an arbitrary integer scale (0 is treated as 1).
pub fn adv_scaled(c: char, scale: i16) -> i16 {
    let s = if scale <= 0 { 1 } else { scale };
    adv(c) * s
}